create index if not exists idx_listening_level_type_order on public.listening_items(level, question_type, sort_order); create index if not exists idx_questions_listening_level_type on public.questions(skill, level, question_type, listening_id); update public.listening_items set source = coalesce(source,'ENO JAPAN original'), audio_license = coalesce(audio_license,'pending_audio_generation') where source is null or audio_license is null;
